// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import { createVisit, updateVisit, getVisit } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:9966");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Request Body
    const visitsPostRequestBody: string = `{
        "date": "2026-08-30",
        "description": "duration persistence check",
        "durationMinutes": 45
    }`;

    const visitsPostResponse = await createVisit(client, 1, 1, visitsPostRequestBody);

    expect(getResponseValue(visitsPostResponse, "id"), 'id').toBeGreaterThan(0);
    expect(getResponseValue(visitsPostResponse, "petId"), 'petId').toBe(1);
    expect(getResponseValue(visitsPostResponse, "date"), 'date').toBe("2026-08-30");
    expect(getResponseValue(visitsPostResponse, "description"), 'description').toBe("duration persistence check");
    expect(getResponseValue(visitsPostResponse, "durationMinutes"), 'durationMinutes').toBe(45);

    // Request Body
    const visitsVisitsPutRequestBody: string = `{
        "date": "2026-08-30",
        "description": "duration persistence check",
        "durationMinutes": 90
    }`;

    const visitsVisitsPutResponse = await updateVisit(client, getResponseValue(visitsPostResponse, "id"), visitsVisitsPutRequestBody);

    const visitsVisitsGetResponse = await getVisit(client, getResponseValue(visitsPostResponse, "id"));

    expect(getResponseValue(visitsVisitsGetResponse, "id"), 'id').toBe(getResponseValue(visitsPostResponse, "id"));
    expect(getResponseValue(visitsVisitsGetResponse, "petId"), 'petId').toBe(1);
    expect(getResponseValue(visitsVisitsGetResponse, "date"), 'date').toBe("2026-08-30");
    expect(getResponseValue(visitsVisitsGetResponse, "description"), 'description').toBe("duration persistence check");
    expect(getResponseValue(visitsVisitsGetResponse, "durationMinutes"), 'durationMinutes').toBe(90);
});
